  align-items: center;
  gap: 4px;
}

.row-label {
  width: $label;
  flex-shrink: 0;
  font-size: 13px;
  color: #555;
}

.seat,
.couch {
  flex-shrink: 0;
  height: $seat;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 6px;
  color: #fff;
  font-size: 12px;
  cursor: pointer;

  &:disabled {
    opacity: 1;
    cursor: not-allowed;
  }

  &[data-state='available'] {
    background-color: #2e7d32;
  }

  &[data-state='selected'] {
    background-color: #f9a825;
    color: #000;
  }

  &[data-state='unavailable'] {
    background-color: #c62828;
  }

  &[data-state='accessible'] {
    background-color: #1565c0;
  }
