import { Component, computed, effect, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { httpResource } from '@angular/common/http';
import { ActivatedRoute, Router } from '@angular/router';
import { API_URL } from '../api';
import { formatShowDate } from '../date';
import { Movie, Screening } from '../models';
import { AuditoriumRow, buildAuditorium } from './auditorium';

@Component({
  selector: 'app-seat-map',
  templateUrl: './seat-map.html',
  styleUrl: './seat-map.scss',
})
export class SeatMap {
  private readonly router = inject(Router);
  private readonly params = toSignal(inject(ActivatedRoute).paramMap, { requireSync: true });

  private readonly screeningResource = httpResource<Screening>(
    () => `${API_URL}/screenings/${this.params().get('id')}`,
  );
  private readonly movieResource = httpResource<Movie>(() => {
    const screening = this.screeningResource.value();
    return screening ? `${API_URL}/movies/${screening.movieId}` : undefined;
  });

  protected readonly screening = computed(() =>
    this.movieResource.hasValue() ? this.screeningResource.value() : undefined,
  );
  protected readonly showDate = computed(() => {
    const screening = this.screening();
    return screening ? formatShowDate(screening.date, screening.time) : '';
  });
  protected readonly rows = computed<AuditoriumRow[]>(() =>
    buildAuditorium(new Set(this.screening()?.occupiedSeats ?? [])),
  );

  constructor() {
    effect(() => {
      if (this.screeningResource.error() || this.movieResource.error()) {
        this.router.navigateByUrl('/', { replaceUrl: true });
      }
    });
  }

}

