export const MAX_SEATS = 10;

const COUCH_ROW = 15;

export interface SelectionLine {
  row: number;
  seats: string;
}

export function describeSelection(ids: ReadonlySet<string>): SelectionLine[] {
  const columnsByRow = new Map<number, number[]>();
  for (const id of ids) {
    const { row, column } = parseSeatId(id);
    columnsByRow.set(row, [...(columnsByRow.get(row) ?? []), column]);
  }
  return [...columnsByRow.entries()]
    .sort(([a], [b]) => a - b)
    .map(([row, columns]) => ({ row, seats: formatSeats(row, columns.sort((a, b) => a - b)) }));
}

function parseSeatId(id: string): { row: number; column: number } {
  const [row, column] = id.slice(1).split('C').map(Number);
  return { row, column };
}

function formatSeats(row: number, columns: number[]): string {
  const labels: string[] = [];
  for (let index = 0; index < columns.length; index++) {
    if (row === COUCH_ROW) {
      labels.push(`${columns[index]}-${columns[index] + 1}`);
      index++;
    } else {
      labels.push(String(columns[index]));
    }
  }
  return labels.join(', ');
}

