  margin: 0 0 16px;
  font-size: 28px;
}

.fields {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;

  mat-form-field {
    width: 100%;
  }
}

.error {
  margin: 0;
  color: #c62828;
  font-size: 12px;
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 16px;
  margin-top: 24px;
}

content.content:
### 3.2 Toasts

Short messages are shown as toasts. Only one toast is visible at a time — a new toast
replaces the current one. A toast stays visible for 4 seconds and then disappears.

---
import { inject, Injectable } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { Toast } from './toast';

const TOAST_DURATION_MS = 4000;

@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(Toast, {
      data: message,
      duration: TOAST_DURATION_MS,
      horizontalPosition: 'center',
      verticalPosition: 'bottom',
    });
  }
}
---
import { Component, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA } from '@angular/material/snack-bar';

@Component({
  selector: 'app-toast',
  template: '{{ message }}',
  host: { 'data-testid': 'toast' },
})
export class Toast {
  protected readonly message = inject<string>(MAT_SNACK_BAR_DATA);
}

